int set_snake_direction(int new_dir) {
    if (new_dir < 0 || new_dir > 3) return 0;
    int cur = *(int *)(0x00404120 + 0x18);
    if ((new_dir == 0 && cur == 2) || (new_dir == 2 && cur == 0) ||
        (new_dir == 3 && cur == 1) || (new_dir == 1 && cur == 3)) return 0;
    *(int *)(0x00404120 + 0x18) = new_dir;
    return 1;
}

int check_snake_collision(int next_x, int next_y) {
    if (next_x < 0 || next_x >= 20 || next_y < 0 || next_y >= 20) return 1;
    int len = *(int *)(0x00404120 + 0x04);
    for (int i = 0; i < len - 1; i++) {
        if (*(int *)(0x00404000 + i * 4) == next_x && *(int *)(0x00404080 + i * 4) == next_y) return 2;
    }
    return 0;
}

void spawn_snake_food(void) {
    int ticks = *(int *)(0x00404120 + 0x14);
    int fx = (ticks * 7 + 13) % 20;
    int fy = (ticks * 11 + 5) % 20;
    *(int *)(0x00404120 + 0x08) = fx;
    *(int *)(0x00404120 + 0x0c) = fy;
}

int check_snake_food(void) {
    int head_x = *(int *)(0x00404000);
    int head_y = *(int *)(0x00404080);
    int food_x = *(int *)(0x00404120 + 0x08);
    int food_y = *(int *)(0x00404120 + 0x0c);
    if (head_x == food_x && head_y == food_y) {
        *(int *)(0x00404120 + 0x00) += 10; // score += 10
        int len = *(int *)(0x00404120 + 0x04);
        if (len < 64) {
            *(int *)(0x00404000 + len * 4) = *(int *)(0x00404000 + (len - 1) * 4);
            *(int *)(0x00404080 + len * 4) = *(int *)(0x00404080 + (len - 1) * 4);
            *(int *)(0x00404120 + 0x04) = len + 1;
        }
        spawn_snake_food();
        return 1;
    }
    return 0;
}

int step_snake_tick(void) {
    if (*(int *)(0x00404120 + 0x10) == 0) return 0;
    *(int *)(0x00404120 + 0x14) += 1; // tick_count++
    int cur_dir = *(int *)(0x00404120 + 0x18);
    /* DETACHED MEMORY: 0x00404100 DIR_DELTAS 2D vector table */
    int dx = *(int *)(0x00404100 + cur_dir * 8);
    int dy = *(int *)(0x00404100 + cur_dir * 8 + 4);
    int next_x = *(int *)(0x00404000) + dx;
    int next_y = *(int *)(0x00404080) + dy;
    if (check_snake_collision(next_x, next_y) != 0) {
        *(int *)(0x00404120 + 0x10) = 0; // is_alive = 0
        return 0;
    }
    int len = *(int *)(0x00404120 + 0x04);
    for (int i = len - 1; i > 0; i--) {
        *(int *)(0x00404000 + i * 4) = *(int *)(0x00404000 + (i - 1) * 4);
        *(int *)(0x00404080 + i * 4) = *(int *)(0x00404080 + (i - 1) * 4);
    }
    *(int *)(0x00404000) = next_x;
    *(int *)(0x00404080) = next_y;
    check_snake_food();
    return 1;
}

